/** Small icon: the Figma 52x52 frame is the medium SVG at 52/256, no crop. */
export function SmallIcon({ name }: { name: IconName | null }) {
	if (!name) return <div style={{ display: "flex", width: 52, height: 52 }} />;
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			width={52}
			height={52}
			viewBox="0 0 256 256"
			fill="#000000"
			role="img"
			aria-label={name}
		>
			<path d={MEDIUM_PATHS[name]} />
		</svg>
	);
}

/**
 * Big icon: the Figma vector is 226.5625 px, which is the thin sun cropped to
 * its content box (12..244 of the 256 viewBox, so 232 units) and scaled
 * 226.5625/232 = 250/256. Cropping the viewBox reproduces that exactly.
 * ASSUMPTION: the same crop box is used for the other eight thin icons (the
 * Figma mockup only has the sun).
 */
export function BigIcon({ name }: { name: IconName | null }) {
	if (!name)
		return (
			<div style={{ display: "flex", width: 226.5625, height: 226.5625 }} />
		);
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			width={226.5625}
			height={226.5625}
			viewBox="12 12 232 232"
			fill="#000000"
			role="img"
			aria-label={name}
		>
			<path d={THIN_PATHS[name]} />
		</svg>
	);
}
